namespace Milan.PrivateCore;
// Local semantic selection only. All physical identities are generated by us.
static class MiniatureCatalog {
  internal static (string IdentityKey,byte[] Data) Get(int slot){
    if(slot>=1&&slot<=7)return ("character-"+slot,[0x10,3,0x10,(byte)slot]);
    return slot switch {
      8 => ("miniature-ally-officer",[0x10,3,0x20,6]),
      9 => ("miniature-ally-reporter",[0x10,3,0x20,7]),
      10 => ("miniature-ghoul-con-artist",[0x10,3,0x30,2]),
      11 => ("miniature-ghoul-fixer",[0x10,3,0x30,1]),
      12 => ("character-8",[0x10,3,0x10,8]),
      13 => ("character-9",[0x10,3,0x10,9]),
      14 => ("character-10",[0x10,3,0x10,10]),
      15 => ("character-11",[0x10,3,0x10,11]),
      16 => ("miniature-ally-food-delivery-driver",[0x10,3,0x20,2]),
      17 => ("miniature-ally-paramedic",[0x10,3,0x20,5]),
      18 => ("miniature-ally-taxi-driver",[0x10,3,0x20,1]),
      19 => ("miniature-ghoul-blood-addict",[0x10,3,0x30,6]),
      20 => ("miniature-ghoul-enforcer",[0x10,3,0x30,4]),
      21 => ("miniature-ghoul-punk",[0x10,3,0x30,7]),
      22 => ("miniature-ally-investigator",[0x10,3,0x20,4]),
      23 => ("miniature-ghoul-burglar",[0x10,3,0x30,3]),
      24 => ("miniature-ally-hacker",[0x10,3,0x20,8]),
      25 => ("miniature-ally-real-estate-agent",[0x10,3,0x20,3]),
      26 => ("miniature-ghoul-vagrant",[0x10,3,0x30,5]),
      _ => throw new ArgumentException("Unknown miniature")
    };
  }
}
